import 'package:flutter/material.dart';\nimport 'package:provider/provider.dart';\nimport '../constants/strings.dart';\nimport '../providers/ai_tools_provider.dart';\nimport '../widgets/ai_tool_card.dart';\n\nclass SearchScreen extends StatefulWidget {\n  const SearchScreen({Key? key}) : super(key: key);\n\n  @override\n  State<SearchScreen> createState() => _SearchScreenState();\n}\n\nclass _SearchScreenState extends State<SearchScreen> {\n  late TextEditingController _searchController;\n\n  @override\n  void initState() {\n    super.initState();\n    _searchController = TextEditingController();\n  }\n\n  @override\n  void dispose() {\n    _searchController.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Consumer<AIToolsProvider>(\n      builder: (context, toolsProvider, _) {\n        return Scaffold(\n          appBar: AppBar(\n            title: Text(AppStrings.search),\n          ),\n          body: Column(\n            children: [\n              Padding(\n                padding: const EdgeInsets.all(16),\n                child: TextField(\n                  controller: _searchController,\n                  onChanged: (value) => toolsProvider.searchTools(value),\n                  decoration: InputDecoration(\n                    hintText: AppStrings.search_hint,\n                    prefixIcon: const Icon(Icons.search),\n                    border: OutlineInputBorder(\n                      borderRadius: BorderRadius.circular(12),\n                    ),\n                  ),\n                ),\n              ),\n              Expanded(\n                child: toolsProvider.filteredTools.isEmpty\n                    ? Center(\n                        child: Column(\n                          mainAxisAlignment: MainAxisAlignment.center,\n                          children: [\n                            Icon(\n                              Icons.search_off,\n                              size: 64,\n                              color: Colors.grey[400],\n                            ),\n                            const SizedBox(height: 16),\n                            Text(\n                              AppStrings.noSearchResults,\n                              style: Theme.of(context).textTheme.bodyLarge,\n                            ),\n                          ],\n                        ),\n                      )\n                    : GridView.builder(\n                        padding: const EdgeInsets.all(16),\n                        gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(\n                          crossAxisCount: 2,\n                          childAspectRatio: 0.85,\n                          mainAxisSpacing: 16,\n                          crossAxisSpacing: 16,\n                        ),\n                        itemCount: toolsProvider.filteredTools.length,\n                        itemBuilder: (context, index) {\n                          return AIToolCard(\n                            tool: toolsProvider.filteredTools[index],\n                          );\n                        },\n                      ),\n              ),\n            ],\n          ),\n        );\n      },\n    );\n  }\n}\n